from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  v=grid[r][c]
  if v in (0,2) or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); comp=[]
  while q:
   x,y=q.pop(); comp.append((x,y,v))
   for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
    if 0<=a<R and 0<=b<C and (a,b) not in seen and grid[a][b]==v:
     seen.add((a,b));q.append((a,b))
  comps.append(comp)
[(min(x for x,y,v in p), min(y for x,y,v in p),p) for p in comps]
